"""Autogenerated migrations must preserve the external hand-off lookup indexes."""

import pytest
from alembic.autogenerate import compare_metadata
from alembic.migration import MigrationContext
from sqlalchemy.orm import Session

from preloop.models import models


@pytest.mark.parametrize(
    ("model", "name"),
    [
        (models.AuditLog, "ix_audit_log_grant_reference"),
        (models.ApprovalRequest, "ix_approval_request_external_notifications"),
    ],
)
def test_external_indexes_survive_autogenerate(
    db_session: Session,
    model: type[models.AuditLog] | type[models.ApprovalRequest],
    name: str,
) -> None:
    """Compare migrated PostgreSQL indexes against the model metadata."""
    assert name in {index.name for index in model.__table__.indexes}
    context = MigrationContext.configure(db_session.connection())
    changes = [
        diff
        for diff in compare_metadata(context, model.metadata)
        if isinstance(diff, tuple)
        and len(diff) > 1
        and getattr(diff[1], "name", None) == name
    ]
    assert changes == []
